using System;
using System.Collections.Generic;

namespace TypeSystemDemo
{
    // 值类型示例：结构体
    public struct Point
    {
        public double X { get; set; }
        public double Y { get; set; }

        public Point(double x, double y)
        {
            X = x;
            Y = y;
        }

        public override string ToString() => $"({X}, {Y})";
    }

    // 引用类型示例：类
    public class Person
    {
        public string Name { get; set; }
        public int Age { get; set; }

        public Person(string name, int age)
        {
            Name = name;
            Age = age;
        }
    }

    class Program
    {
        static void Main()
        {
            // 值类型赋值是复制
            Point p1 = new Point(1, 2);
            Point p2 = p1; // 复制值
            p2.X = 10;
            Console.WriteLine($"p1: {p1}"); // (1, 2) - 不受影响
            Console.WriteLine($"p2: {p2}"); // (10, 2)

            // 引用类型赋值是共享引用
            Person person1 = new Person("Alice", 25);
            Person person2 = person1; // 共享引用
            person2.Name = "Bob";
            Console.WriteLine($"person1.Name: {person1.Name}"); // Bob - 受影响

            // 装箱拆箱示例
            int number = 42;
            object boxed = number; // 装箱
            int unboxed = (int)boxed; // 拆箱

            // 可空类型
            int? nullableInt = null;
            Console.WriteLine(nullableInt.HasValue); // false

            nullableInt = 100;
            Console.WriteLine(nullableInt.Value); // 100

            // 空合并运算符
            int result = nullableInt ?? 0;
            Console.WriteLine(result); // 100

            // 泛型集合避免装箱
            List<int> numbers = new List<int> { 1, 2, 3 }; // 无装箱
            // ArrayList arrayList = new ArrayList { 1, 2, 3 }; // 有装箱
        }
    }
}
